using Keynote.Input;
using Keynote.Core;
namespace Keynote.Tests;
public class WindowsInputTests {
 [Fact] public void NativePacketsUseMatchingPhysicalScanCodesForDownAndUp() { var down=WindowsKeyboardInput.CreateScanCodeInput(0x10,false); var up=WindowsKeyboardInput.CreateScanCodeInput(0x10,true); Assert.Equal(0,down.wVk); Assert.Equal(0,up.wVk); Assert.Equal(0x10,down.wScan); Assert.Equal(down.wScan,up.wScan); Assert.Equal(0x0008u,down.dwFlags); Assert.Equal(0x000Au,up.dwFlags); }
 [Fact] public void ExtendedScanCodeRetainsItsFlagOnRelease() { var down=WindowsKeyboardInput.CreateScanCodeInput(0xE01D,false); var up=WindowsKeyboardInput.CreateScanCodeInput(0xE01D,true); Assert.Equal(0x1D,down.wScan); Assert.Equal(0x0009u,down.dwFlags); Assert.Equal(0x000Bu,up.dwFlags); }
 [Theory] [InlineData(0u)] [InlineData(0xE000u)] [InlineData(0xE11Du)] [InlineData(0x10010u)] public void UnmappedOrUnsupportedScanCodesAreRejected(uint scanCode)=>Assert.Throws<InvalidOperationException>(()=>WindowsKeyboardInput.CreateScanCodeInput(scanCode,false));
 [Fact] public void ShiftIsReleasedBeforeNextNaturalChordNote() { var p=new Platform(); using var input=new WindowsKeyboardInput(p){Target=1}; input.Press("SHIFT+A"); input.Press("B"); Assert.Equal(new[]{((ushort)160,false),((ushort)65,false),((ushort)160,true),((ushort)66,false)},p.Sent); Assert.Equal(new[]{"SHIFT+A","B"},input.HeldKeys); input.Release("A"); Assert.Equal(4,p.Sent.Count); input.ReleaseAll(); Assert.Empty(input.HeldKeys); }
 [Fact] public void ShiftCleanupFailureIsRetainedAndRetried() { var p=new Platform(); var input=new WindowsKeyboardInput(p){Target=1}; p.FailRelease.Add(160); Assert.Throws<InvalidOperationException>(()=>input.Press("SHIFT+A")); Assert.Contains("Shift",input.HeldKeys); p.FailRelease.Clear(); input.ReleaseAll(); Assert.Empty(input.HeldKeys); Assert.Equal(2,p.Sent.Count(x=>x==((ushort)160,true))); input.Dispose(); }
 [Theory] [InlineData(0x10)] [InlineData(0x11)] [InlineData(0x12)]
 public void RefusesPhysicalModifiers(int modifier) { var p=new Platform(); p.Down.Add((ushort)modifier); using var input=new WindowsKeyboardInput(p){Target=1}; Assert.Throws<KeyboardInputBusyException>(()=>input.Press("SHIFT+A")); Assert.Empty(p.Sent); }
 [Fact] public void DoesNotReleaseAnotherBindingOfSamePhysicalKey() { var p=new Platform(); using var input=new WindowsKeyboardInput(p){Target=1}; input.Press("A"); Assert.Throws<InvalidOperationException>(()=>input.Press("SHIFT+A")); input.Release("SHIFT+A"); Assert.Single(input.HeldKeys); input.Release("A"); Assert.Empty(input.HeldKeys); }
 sealed class Platform : IWindowsInputPlatform { public bool Focus=true; public HashSet<ushort> Down=new(); public List<(ushort,bool)> Sent=new(); public HashSet<ushort> FailRelease=new(); public bool IsTargetForeground(nint target,uint expectedProcessId)=>Focus && target!=0; public bool IsKeyDown(ushort key)=>Down.Contains(key); public void SendKey(ushort key,bool up) { Sent.Add((key,up)); if(up && FailRelease.Contains(key)) throw new InvalidOperationException("release failed"); } }
 [Fact] public void RequiresForegroundAndPairsOnlyOwnedKeys() { var p=new Platform(); using var input=new WindowsKeyboardInput(p){Target=1}; p.Focus=false; Assert.Throws<InvalidOperationException>(()=>input.Press("A")); Assert.Empty(p.Sent); p.Focus=true; input.Press("a"); input.Press("A"); input.Release("S"); input.Release("A"); input.Release("A"); Assert.Equal(new[]{((ushort)65,false),((ushort)65,true)},p.Sent); }
 [Fact] public void RefusesAlreadyHeldPhysicalKey() { var p=new Platform(); p.Down.Add(65); using var input=new WindowsKeyboardInput(p){Target=1}; Assert.Throws<KeyboardInputBusyException>(()=>input.Press("A")); Assert.Empty(p.Sent); }
 [Fact] public void ReleaseAllAttemptsEveryKeyAndRetriesFailures() { var p=new Platform(); var input=new WindowsKeyboardInput(p){Target=1}; input.Press("A"); input.Press("B"); p.FailRelease.Add(65); Assert.Throws<AggregateException>(()=>input.ReleaseAll()); Assert.Contains(((ushort)66,true),p.Sent); p.FailRelease.Clear(); input.ReleaseAll(); Assert.Equal(2,p.Sent.Count(x=>x==((ushort)65,true))); Assert.Equal(1,p.Sent.Count(x=>x==((ushort)66,true))); input.Dispose(); }
 [Fact] public void FocusLossStillReleasesOnlyOwnedKeys() { var p=new Platform(); var input=new WindowsKeyboardInput(p){Target=1}; input.Press("A"); p.Focus=false; input.Dispose(); Assert.Equal(new[]{((ushort)65,false),((ushort)65,true)},p.Sent); }
}
